#!/usr/bin/env python3
import sys, os, io, csv, json, gzip, glob
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8-sig')
    return t


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip() != '']


def to_ts(dt):
    return int((dt - EPOCH) // timedelta(seconds=1))


def from_ts(ts):
    return EPOCH + timedelta(seconds=ts)


def local_to_ts(naive, tz, fold=0):
    return to_ts(naive.replace(tzinfo=tz, fold=fold).astimezone(UTC))


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt


def std_offset(tz, ts):
    dt = from_ts(ts).astimezone(tz)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


def fold_for(abbr, ambiguous_default=0):
    a = (abbr or '').strip().upper()
    if a.endswith('DT'):
        return 0
    if a.endswith('ST'):
        return 1
    return ambiguous_default


def parse_abbr(path, tz):
    out = []
    hdr = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]]
        d = datetime.strptime(g('Date'), '%m/%d/%Y')
        tm = g('Time').upper()
        ap = None
        if tm.endswith('AM') or tm.endswith('PM'):
            ap = tm[-2:]
            tm = tm[:-2].strip()
        h, m, s = [int(x) for x in tm.split(':')]
        if ap:
            h = h % 12 + (12 if ap == 'PM' else 0)
        naive = d.replace(hour=h, minute=m, second=s)
        ts = local_to_ts(naive, tz, fold_for(g('Zone')))
        out.append((g('Record'), g('Badge'), g('Punch').strip().upper(), ts))
    return out


def parse_epoch(path):
    out = []
    schema = 1
    for line in lines_of(path):
        try:
            o = json.loads(line)
        except Exception:
            continue
        if not isinstance(o, dict):
            continue
        if 'schema' in o and 'heartbeat' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ms = o.get('punch_id'), o.get('employee'), o.get('direction'), o.get('epoch_ms')
            if pid is None or ms is None:
                continue
            ts = int(ms // 1000)
        else:
            pid, emp, d = o.get('id'), o.get('emp'), o.get('dir')
            if 'ts_ms' in o:
                ts = int(o['ts_ms'] // 1000)
            elif 'ts' in o:
                ts = int(o['ts'] // 1)
            else:
                continue
        out.append((str(pid), emp, str(d).upper(), ts))
    return out


def parse_offset(path):
    out = []
    ls = lines_of(path)
    rows = csv.DictReader(ls, delimiter=';', quotechar='"')
    for r in rows:
        ev = r['event'].strip().lower()
        d = 'IN' if ev == 'clock_in' else 'OUT'
        out.append((r['punch_id'], r['employee'], d, to_ts(parse_iso(r['timestamp']))))
    return out


def parse_legacy(path, tz):
    out = []
    cur_off = None
    for line in read_text(path).splitlines():
        if not line.strip():
            continue
        t = line[0]
        if t == 'H':
            off = line[13:18].strip()
            cur_off = None
            if len(off) == 5 and off[0] in '+-':
                mins = int(off[1:3]) * 60 + int(off[3:5])
                cur_off = timedelta(minutes=mins if off[0] == '+' else -mins)
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            d = 'IN' if line[15] == 'I' else 'OUT'
            naive = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
            if cur_off is not None:
                off = cur_off
            else:
                # standard offset of the site zone (constant all year; probe on that date)
                probe = to_ts(naive.replace(tzinfo=UTC))
                off = std_offset(tz, probe)
            ts = to_ts(naive.replace(tzinfo=UTC) - off)
            out.append((pid, 'E' + badge, d, ts))
    return out


def parse_de(path, tz):
    out = []
    for r in csv.DictReader(lines_of(path), delimiter='\t'):
        r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
        naive = datetime.strptime(r['Datum'] + ' ' + r['Uhrzeit'], '%d.%m.%Y %H:%M')
        fold = 0 if r['Zeitzone'].upper() == 'MESZ' else 1
        d = 'IN' if r['Buchung'].upper() == 'K' else 'OUT'
        out.append((r['Nr'], r['Ausweis'], d, local_to_ts(naive, tz, fold)))
    return out


def parse_localcsv(path, tz):
    out = []
    for r in csv.DictReader(lines_of(path)):
        r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
        naive = datetime.strptime(r['local_time'], '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'], r['employee_id'], r['direction'].upper(), local_to_ts(naive, tz, 0)))
    return out


def parse_localjsonl(path, tz):
    out = []
    for line in lines_of(path):
        try:
            o = json.loads(line)
        except Exception:
            continue
        p = o.get('punch') if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        pid = p['id']
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid)
        out.append((pid, p['badge'], str(p['type']).upper(), local_to_ts(naive, tz, 0)))
    return out


def round_ts(ts, tz):
    off = int(from_ts(ts).astimezone(tz).utcoffset().total_seconds())
    loc = ts + off
    r = loc % 360
    if r >= 180:
        return ts + (360 - r)
    return ts - r


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])

    def rcsv(name):
        with open(os.path.join(inp, name), encoding='utf-8-sig', newline='') as f:
            return [{k.strip(): (v or '').strip() for k, v in r.items()} for r in csv.DictReader(f)]

    sites = {r['site']: (ZoneInfo(r['timezone']), r['format']) for r in rcsv('sites.csv')}
    emps = rcsv('employees.csv')
    home = {e['employee_id']: sites[e['home_site']][0] for e in emps}
    rates = {}
    for r in rcsv('rates.csv'):
        rates.setdefault(r['employee_id'], []).append((date.fromisoformat(r['effective_from']), Fraction(Decimal(r['hourly_rate']))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    punches = {}  # (site,id) -> dict
    existed = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for path in sorted(glob.glob(os.path.join(d, '**', '*'), recursive=True)):
            if not os.path.isfile(path):
                continue
            if fmt == 'abbr-csv': recs = parse_abbr(path, tz)
            elif fmt == 'epoch-jsonl': recs = parse_epoch(path)
            elif fmt == 'offset-csv': recs = parse_offset(path)
            elif fmt == 'legacy-fixed': recs = parse_legacy(path, tz)
            elif fmt == 'de-tsv': recs = parse_de(path, tz)
            elif fmt == 'local-csv': recs = parse_localcsv(path, tz)
            elif fmt == 'local-jsonl': recs = parse_localjsonl(path, tz)
            else: recs = []
            for pid, emp, dr, ts in recs:
                k = (site, str(pid))
                existed.add(k)
                if k not in punches:
                    punches[k] = {'emp': emp, 'dir': dr, 'ts': ts}

    # corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for path in sorted(glob.glob(os.path.join(cdir, '**', '*'), recursive=True)):
            if os.path.isfile(path):
                for r in csv.DictReader(lines_of(path)):
                    r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                    corr.append(r)
    corr = [(parse_iso(r['issued_at']), r['correction_id'], r) for r in corr]
    corr = [c for c in corr if c[0] <= cutoff]
    corr.sort(key=lambda c: (c[0], c[1]))
    applied = 0
    for _, _, r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]; applied += 1
        elif a == 'set':
            if k in punches:
                punches[k]['ts'] = to_ts(parse_iso(r['time'])); applied += 1
        elif a == 'add':
            if k not in existed and r['site'] in sites:
                existed.add(k)
                punches[k] = {'emp': r['employee'], 'dir': r['type'].upper(), 'ts': to_ts(parse_iso(r['time']))}
                applied += 1

    byemp = {}
    for (site, pid), p in punches.items():
        if p['emp'] in home:
            byemp.setdefault(p['emp'], []).append((p['ts'], 0 if p['dir'] == 'OUT' else 1, site, pid, p['dir']))

    res = {e['employee_id']: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def inperiod(rts, hz):
        d = from_ts(rts).astimezone(hz).date()
        return pstart <= d <= pend, d

    for emp, lst in byemp.items():
        hz = home[emp]
        lst.sort()
        kept = []
        for ts, _, site, pid, dr in lst:
            rts = round_ts(ts, sites[site][0])
            if kept and kept[-1][4] == dr and ts - kept[-1][0] <= 300:
                if inperiod(rts, hz)[0]:
                    exc['duplicates_dropped'] += 1
                continue
            kept.append((ts, rts, site, pid, dr))
        shifts = []
        pend_in = None

        def open_in(p):
            if inperiod(p[1], hz)[0]:
                exc['open_shifts'] += 1
        for p in kept:
            if p[4] == 'IN':
                if pend_in:
                    open_in(pend_in)
                pend_in = p
            else:
                if pend_in and p[1] - pend_in[1] <= 16 * 3600:
                    shifts.append((pend_in, p)); pend_in = None
                else:
                    if pend_in:
                        open_in(pend_in); pend_in = None
                    if inperiod(p[1], hz)[0]:
                        exc['orphan_outs'] += 1
        if pend_in:
            open_in(pend_in)

        items = []
        for i, o in shifts:
            ok, wd = inperiod(i[1], hz)
            if not ok:
                continue
            tz = sites[i[2]][0]
            worked = max(0, (o[1] - i[1]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = 0
            for m in range(worked):
                h = from_ts(i[1] + m * 60).astimezone(tz).hour
                if h >= 22 or h < 6:
                    night += 1
            night = min(night, paid)
            items.append([i[1], wd, paid, night, 0])
        items.sort(key=lambda x: x[0])
        daily = {}
        weekly = {}
        rl = rates.get(emp, [])
        r = res[emp]
        for it in items:
            _, wd, paid, night, _ = it
            before = daily.get(wd, 0)
            dot = max(0, before + paid - 480) - max(0, before - 480)
            daily[wd] = before + paid
            wk = wd - timedelta(days=wd.weekday())
            nd = paid - dot
            wb = weekly.get(wk, 0)
            wot = max(0, wb + nd - 2400) - max(0, wb - 2400)
            weekly[wk] = wb + nd
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, rt in rl:
                if ef <= wd:
                    rate = rt
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r['shifts'] += 1; r['paid_minutes'] += paid; r['overtime_minutes'] += ot
            r['night_minutes'] += night; r['gross'] += pay

    def money(f):
        c = int((f * 100 + Fraction(1, 2)) // 1)
        return '%d.%02d' % (c // 100, c % 100)

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totg = 0
    for e, r in res.items():
        g = money(r['gross'])
        out_emps[e] = dict(shifts=r['shifts'], paid_minutes=r['paid_minutes'], overtime_minutes=r['overtime_minutes'],
                           night_minutes=r['night_minutes'], gross=g)
        for k in tot: tot[k] += r[k]
        totg += int(g.replace('.', ''))
    tot['gross'] = '%d.%02d' % (totg // 100, totg % 100)
    with open(outp, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']}, 'employees': out_emps,
                   'exceptions': exc, 'totals': tot}, f, indent=1)


main()
